mapper.delete:
delete from ssd_field_exclude
where
ctg_id = #{categoryId}
AND exclude_ctg_id = #{excludeCategoryId}

mapper.select:
select e1.excludeId FROM ( select
sfd.field_id AS excludeId
t.exclude_ctg_id AS excludeId
from ssd_field_exclude t left join ssd_field_def sfd on t.exclude_field_code = sfd.field_code where
t.field_code = #{code}
t.ctg_id = #{categoryId}
UNION ALL select
sfd.field_id AS excludeId
t.ctg_id AS excludeId
from ssd_field_exclude t left join ssd_field_def sfd on t.field_code = sfd.field_code where
t.exclude_field_code = #{code}
t.exclude_ctg_id = #{categoryId}
) e1 GROUP BY e1.excludeId

select exclude_desc from ssd_field_exclude
where


        field_code = #{code}


        ctg_id = #{categoryId}


limit 0,1
